    header, body = rows[0], rows[1:]
    if columns is None:
        columns = {h: h for h in header}
    known = table_columns(conn, table)
    for col, src in columns.items():
        if col not in known:
            raise BuildError(f"{where}: table {table} has no column {col}")
        if src not in header:
            raise BuildError(f"{where}: no field {src} in the header")
    for col in maps:
        if col not in columns:
            raise BuildError(f"{where}: map for {col}, which is not loaded")
    order = list(columns)
    idx = [header.index(columns[c]) for c in order]
    sql = f"INSERT INTO {table} ({', '.join(order)}) VALUES ({', '.join('?' for _ in order)})"
    conn.execute("BEGIN")
    try:
        if seed.get("deferred", False):
            conn.execute("PRAGMA defer_foreign_keys = ON")
        for line, row in enumerate(body, start=2):
            if len(row) != len(header):
                raise BuildError(f"{where} line {line}: {len(row)} fields, header has {len(header)}")
            values = []
            for c, i in zip(order, idx):
                v = row[i]
                if v in nulls:
                    values.append(None)
                    continue
                values.append(maps.get(c, {}).get(v, v))
            try:
                conn.execute(sql, values)
            except sqlite3.Error as e:
                raise BuildError(f"{where} line {line}: {e}")
        try:
            conn.execute("COMMIT")
        except sqlite3.Error as e:
            raise BuildError(f"{where}: {e}")
    except BuildError:
        if conn.in_transaction:
            conn.execute("ROLLBACK")
        raise

arguments.command:
cd /app; cp releases/1.6.0/herbarium.sqlite /tmp/u.sqlite; python3 tools/stratum.py upgrade /tmp/u.sqlite 2>&1|tail -2; python3 - <<'E'
import sqlite3
a=sqlite3.connect('build/herbarium.sqlite');b=sqlite3.connect('/tmp/u.sqlite')
def sch(c): return sorted((r[0],r[1],r[2]) for r in c.execute("select type,name,sql from sqlite_master where name not like 'sqlite_%'"))
sa,sb=sch(a),sch(b)
for x,y in zip(sa,sb):
    if x!=y: print(x,'\n',y)
print(len(sa),len(sb))
for t in ['site','collector','taxon','specimen']:
    ra=set(a.execute(f"select * from {t}"));rb=set(b.execute(f"select * from {t}"))
    print(t,len(ra),len(rb),list(ra-rb)[:3],list(rb-ra)[:3])
E

